Lemma shadow_rep_frame : forall st m a bs rid r,
  0 <= a -> a + Z.of_nat (length bs) <= 2^64 ->
  (r_base r + round_up_pg (r_len r) <= a \/ a + Z.of_nat (length bs) <= r_base r) ->
  shadow_rep st m rid r -> shadow_rep st (write_to_mem m (wa a) bs) rid r.
