Definition implT {R} (o : mem) (t : Malloc.M R) (s : PState)
           (Q : R -> PState -> machine_state -> Prop) (ms : machine_state) : Prop :=
  implM asegs (membed (mrun o t)) s (fun r s' ms' => Q (snd r) s' ms') ms.

